import {PEOPLE} from './life.js';import {placements,BODIES,SIZES,METHODS} from './architecture.js';
const slot='tsugime.transport.stage9.v1';
export function snapshot(s){if(s.mode!=='idle'||s.anyLiftActive)throw Error('搬送・EVの完了後に保存してください。');return{schema:1,phase:s.phase,experiment:s.experiment,player:s.player,doors:s.doors,doorTargets:s.experience.doorTargets,doorProgress:s.experience.doorProgress,life:{time:s.life.time,states:s.life.states},items:{counts:s.items.counts,flags:s.items.flags,results:s.items.results,mode:s.items.mode,selected:s.items.selected},trade:s.experience.trade,liftY:s.liftY,localLift:s.localLift,visit:s.experience.visit,dialogue:s.experience.dialogue,clock:s.clock};}
export function restore(s,input){const d=structuredClone(input);if(!d||![0,1].includes(d.schema??0)||!['A','B','C'].includes(d.phase))throw Error('未対応または破損した保存データ');const e=d.experiment??s.experiment;if(!SIZES[e.size]||!METHODS[e.method])throw Error('保存された搬送条件が不正');const states=d.life?.states;if(states)for(const n of PEOPLE){const r=states[n.id];if(!r||!['home','work'].includes(r.location)||!Number.isFinite(r.cover)||r.cover<0||r.cover>1)throw Error('NPC保存状態が不正');}if(d.player&&!['x','y','z','yaw','pitch'].every(k=>Number.isFinite(d.player[k])))throw Error('プレイヤー座標が不正');for(const v of Object.values(d.doorProgress??{}))if(!Number.isFinite(v)||v<0||v>1)throw Error('扉の保存状態が不正');const counts=d.items?.counts??d.inventory??{};for(const v of Object.values(counts))if(!Number.isInteger(v)||v<0)throw Error('所持数が不正');if(!Number.isFinite(d.life?.time??d.clock??0))throw Error('時計が不正');
 s.reset(e);s.phase=d.phase;s.positions=placements(d.phase,e);if(d.player&&['x','y','z','yaw','pitch'].every(k=>Number.isFinite(d.player[k])))s.player=d.player;for(const id of Object.keys(s.doors)){s.doors[id]=d.doors?.[id]??false;s.experience.doorTargets[id]=d.doorTargets?.[id]??s.doors[id];s.experience.doorProgress[id]=d.doorProgress?.[id]??(s.doors[id]?1:0);}s.life.time=d.life?.time??d.clock??0;if(states)s.life.states=states;s.items.counts=counts;s.items.flags=d.items?.flags??{};s.items.results=d.items?.results??[];s.items.mode=['browse','use','trade'].includes(d.items?.mode)?d.items.mode:null;s.items.selected=d.items?.selected??null;if(d.trade&&PEOPLE.some(n=>n.id===d.trade)&&s.life.states[d.trade].location==='work'){s.experience.trade=d.trade;s.items.mode='trade';}s.clock=d.clock??0;s.liftY=[-12.8,0,12.8].includes(d.liftY)?d.liftY:12.8;if(d.localLift&&!d.localLift.liftActive)s.localLift=d.localLift;if(d.visit&&PEOPLE.some(n=>n.id===d.visit.npc&&n.home.body===d.visit.body)&&s.life.states[d.visit.npc].location==='home'){s.experience.visit=d.visit;s.experience.lastVisitDoor=PEOPLE.find(n=>n.id===d.visit.npc).home.door;s.experience.focus={...PEOPLE.find(n=>n.id===d.visit.npc),...PEOPLE.find(n=>n.id===d.visit.npc).home};s.experience.blend=1;}if(d.dialogue&&PEOPLE.some(n=>n.id===d.dialogue.npc.id))s.experience.dialogue=d.dialogue;s.invalidate();s.message='生活時計・所在・所持品・搬送配置を復元しました。';return true;}
export function saveLocal(s,storage=globalThis.localStorage){const data=snapshot(s);storage.setItem(slot,JSON.stringify(data));return data;}
export function loadLocal(s,storage=globalThis.localStorage){const raw=storage.getItem(slot);if(!raw)throw Error('この実験の保存データはありません。');return restore(s,JSON.parse(raw));}
